#include <iostream>

// Global variable (static storage duration, global namespace scope)
int globalCounter = 100;

void demonstrateStorage() {
    // Automatic variable: re-created and initialized each call
    int autoVar = 1;

    // Static local variable: initialized ONCE, retains value across calls
    static int staticVar = 1;

    std::cout << "autoVar: " << autoVar 
              << " | staticVar: " << staticVar 
              << " | globalCounter: " << globalCounter << "\n";

    ++autoVar;
    ++staticVar;
    globalCounter += 10;
}

int main() {
    for (int i = 0; i < 3; ++i) {
        std::cout << "Call " << (i + 1) << ": ";
        demonstrateStorage();
    }
    return 0;
}

#include <iostream>

int x = 10; // Global variable (global namespace scope)

int main() {
    std::cout << "Global x: " << x << "\n";

    int x = 25; // Block scope in main: shadows global x
    std::cout << "Local x in main: " << x << " (Global x via ::x is " << ::x << ")\n";

    {
        // Nested inner block
        int x = 99; // Shadows main's local x
        std::cout << "Inner block x: " << x << "\n";
    }

    // Inner block ended; main's local x is active again
    std::cout << "Local x in main after inner block: " << x << "\n";

    return 0;
}
